function dz_badge(string $sym = 'f', string $cls = ''): string {
    if (!in_array($sym, ['f', 'o', 'r'], true)) $sym = 'f';
    return '<svg class="vbadge ' . htmlspecialchars($cls, ENT_QUOTES) . '" viewBox="0 0 256 256" role="img" aria-label="Verified" '
         . 'style="width:1em;height:1em;flex-shrink:0;display:inline-block;vertical-align:-.15em;color:inherit"><use href="#dz-flower-' . $sym . '"/></svg>';
}